//! 🧪️ The original canonical DTO moves every native field under one initiating caller and real System receipts.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,StepContext,OperationId,Generation};
use crate::component_reference_custody_tests::observe_retirement_allocations as observe;
const STOCK:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:64};
fn grant(d:RetirementDemand,body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(29),Generation(7),STOCK,||Some(1),u64::MAX,1<<40)}
fn run<R>(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,fuel:u64,deadline:u64,advance:impl FnOnce(&mut StepContext<'_>)->R)->R{let mut out=None;caller.turn(grant,|cx|cx.with_original_work_loan(fuel,deadline,|cx|{out=Some(advance(cx));Ok(())})).unwrap_or_else(|_|panic!("original fixture turn"));out.unwrap_or_else(||unreachable!())}
fn dto(value:&serde_json::Value)->DslValue{match value{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(value)=>DslValue::Bool(*value),serde_json::Value::Number(value)=>DslValue::Number(value.as_u64().map(Number::UInt).unwrap_or_else(||Number::Float(value.as_f64().unwrap()))),serde_json::Value::String(value)=>DslValue::String(value.clone()),serde_json::Value::Array(value)=>DslValue::Array(value.iter().map(dto).collect()),serde_json::Value::Object(value)=>DslValue::Object(value.iter().map(|(key,value)|(key.clone(),dto(value))).collect())}}
fn close(owner:&mut MeshCanonicalDecoder,caller:&mut OriginalJobFixtureCaller,body:usize)->(usize,usize){let mut sum=(0,0);for turn in 0..200000{if owner.terminal_is_empty(){return sum}assert!(turn<199999);owner.begin_close();let d=owner.next_close_demands(body).unwrap();let g=grant(d,body);let(step,heap)=run(caller,g,1,u64::MAX,|cx|observe(||owner.close_step(cx)));let p=caller.receipt();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(step.unwrap().progress(),p);sum.0+=heap.0;sum.1+=heap.1;}unreachable!()}

#[test]
fn original_mesh_canonical_decoder_preserves_mesh16_and_paid_physical_source(){
 let fixture:serde_json::Value=serde_json::from_str(crate::test_inputs::text("🌲️canonical/📥️decode/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let oracle:MeshData=serde_json::from_value(fixture["mesh"].clone()).unwrap();oracle.validate_component_references().unwrap();
 for body in [1,3,64]{let(source,source_heap)=observe(||dto(&fixture["mesh"]));let source_pointer=object(&source).unwrap().as_ptr();let mut original=caller();let(mut owner,heap)=run(&mut original,RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()},1,u64::MAX,|cx|observe(||MeshCanonicalDecoder::new(source,cx).unwrap_or_else(|_|panic!("original native intake"))));assert_eq!(heap,(0,0));assert_eq!(object(owner.state.as_ref().unwrap().source.as_ref().unwrap()).unwrap().as_ptr(),source_pointer);let mut sums=(source_heap.0,source_heap.1);
 for turn in 0..200000{if owner.ready(){break}assert!(turn<199999);let d=owner.next_demands(body).unwrap();let g=grant(d,body);for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}),(d.copy_bytes>0&&owner.next_demands(d.copy_bytes-1).unwrap().copy_bytes>d.copy_bytes-1).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})].into_iter().flatten(){let(result,heap,fuel)=run(&mut original,denied,1,u64::MAX,|cx|{let(result,heap)=observe(||owner.step(cx));(result,heap,cx.fuel_remaining())});assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(original.receipt(),Default::default());assert_eq!(fuel,1);}
 for(fuel,deadline)in[(0,u64::MAX),(1,1)]{let(result,heap,remaining)=run(&mut original,g,fuel,deadline,|cx|{let(result,heap)=observe(||owner.step(cx));(result,heap,cx.fuel_remaining())});assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(original.receipt(),Default::default());assert_eq!(remaining,fuel);}
 let(result,heap)=run(&mut original,g,1,u64::MAX,|cx|observe(||owner.step(cx)));let p=original.receipt();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;result.unwrap();if d.copy_bytes>body{assert_eq!(p,Default::default());break}}
 assert_eq!(owner.ready(),body>=64);if !owner.ready(){original.cancel().cancel_now();let d=owner.next_demands(body).unwrap();let(result,heap)=run(&mut original,grant(d,body),1,u64::MAX,|cx|observe(||owner.step(cx)));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(original.receipt(),Default::default());}if owner.ready(){assert_eq!(serde_json::to_value(owner.state.as_ref().unwrap().mesh.as_ref().unwrap()).unwrap(),serde_json::to_value(&oracle).unwrap())}let closed=close(&mut owner,&mut original,body);sums.0+=closed.0;sums.1+=closed.1;assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(owner)).1,(0,0));original.retire(STOCK);}
}

#[test]
fn original_mesh_canonical_decoder_keeps_failed_picking_source_and_exact_turn_receipt(){
 let fixture:serde_json::Value=serde_json::from_str(crate::test_inputs::text("🌲️canonical/📥️decode/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut input=fixture["mesh"].clone();input["vertexIds"][0]=serde_json::json!(99);let oracle:MeshData=serde_json::from_value(input.clone()).unwrap();assert!(oracle.validate_component_references().is_err());let(source,source_heap)=observe(||dto(&input));let source_pointer=object(&source).unwrap().as_ptr();let mut original=caller();let mut owner=run(&mut original,RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()},1,u64::MAX,|cx|MeshCanonicalDecoder::new(source,cx).unwrap_or_else(|_|panic!("original failed picking intake")));let mut sums=(source_heap.0,source_heap.1);let mut failed=false;
 for turn in 0..200000{assert!(turn<199999);let d=owner.next_demands(64).unwrap();let(result,heap,fuel)=run(&mut original,grant(d,64),1,u64::MAX,|cx|{let(result,heap)=observe(||owner.step(cx));(result,heap,cx.fuel_remaining())});let p=original.receipt();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;if let Err(error)=result{assert_eq!(error.primary_value().unwrap().kind,ValueRefusalKind::InvalidValue);assert_eq!(p.copied_bytes,4);assert_eq!(fuel,0);assert!(error.receipt_refusal.is_none());failed=true;break}}
 assert!(failed&&!owner.ready());assert_eq!(object(owner.state.as_ref().unwrap().source.as_ref().unwrap()).unwrap().as_ptr(),source_pointer);original.cancel().cancel_now();let returned=close(&mut owner,&mut original,3);sums.0+=returned.0;sums.1+=returned.1;assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(owner)).1,(0,0));original.retire(STOCK);
}
